export interface Request {
  url: string;
}

export interface Reply {
  send(body: unknown): void;
}

export type Handler = (request: Request, reply: Reply) => unknown;

export interface PluginOptions {
  prefix?: string;
  [key: string]: unknown;
}

export interface App {
  get(path: string, handler: Handler): App;
  post(path: string, handler: Handler): App;
  /** Runs `plugin` with an app whose routes are served under `options.prefix`. */
  register(plugin: (app: App, options: any) => unknown, options?: PluginOptions): App;
  /** Runs `fn` with an app whose routes are served under `prefix`. */
  group(prefix: string, fn: (app: App) => unknown): App;
  addHook(name: string, hook: (...args: any[]) => unknown): App;
  setErrorHandler(handler: (error: Error, request: Request, reply: Reply) => unknown): App;
}

declare function server(): App;
export default server;
